 fresh:T('frisch','fresh','frais'),herbal:T('kräutrig','herbal','herbacé'),delicate:T('zart','delicate','délicat'),roasted:T('geröstet','roasted','grillé'),creamy:T('cremig','creamy','crémeux'),rich:T('kräftig','rich','intense'),saline:T('salzig','saline','salin'),marine:T('maritim','marine','marin'),earthy:T('erdig','earthy','terreux'),umami:T('umami','umami','umami'),fruity:T('fruchtig','fruity','fruité'),sweet:T('süß','sweet','sucré'),spicy:T('scharf','hot','piquant'),cool:T('kühl','cool','frais'),light:T('leicht','light','léger'),tangy:T('säuerlich','tangy','acidulé'),bitter:T('herb','bitter','amer'),cocoa:T('kakaointensiv','deep cocoa','cacaoté'),nutty:T('nussig','nutty','notes de noisette')
