function flavourPlate(d,v){return `<div class="flavour-plate"><svg class="plate-line" viewBox="0 0 440 390" aria-hidden="true"><path d="M349 49C279 9 157 19 87 79C22 131 23 236 76 295C131 358 260 372 339 320C418 267 430 163 383 96M371 79L362 68"/><path class="second-line" d="M338 58C265 27 161 38 101 90C53 130 39 222 85 276M117 316C175 350 267 345 316 317"/></svg><div class="plate-copy"><p class="plate-label">${txt(T('Auf dem Teller','On the plate','Dans l’assiette'))}</p><h2>${txt(d.name)}</h2><div class="flavour-words" aria-live="polite">${v.flavours.map((key,i)=>`<span class="flavour-word flavour-${key} tone-${i}">${txt(flavourWords[key])}</span>`).join('')}</div></div></div><p class="plate-preparation">${txt(v.name)}</p><p class="plate-description">${txt(v.profile)}</p>`;}
const plainLabPage=labPage;
labPage=function(){const d=DISHES[pairDish],v=d.variants[pairVariant];return plainLabPage().replace(/<div class="dish-stage">[\s\S]*?<\/div><\/section>/,`<div class="dish-stage sensory-stage">${flavourPlate(d,v)}</div></section>`);};
const basicPairResult=pairResult;
pairResult=function(v,drinks){
 const reason=pairMode==='zero'?v.whyZero:v.why;
 let result=basicPairResult({...v,why:reason},drinks);
 return result.replace(/<\/div>$/,`<button class="text-button try-another" id="try-another">${txt(T('Andere Begleitung ausprobieren','Try another drink','Essayer une autre boisson'))}${arrow}</button></div>`);
};
const profileBindLab=bindLab;
bindLab=function(){profileBindLab();$('#try-another')?.addEventListener('click',()=>{pairRevealed=false;render(false);$('#drink-select')?.focus({preventScroll:true});$('#drink-select')?.scrollIntoView({block:'center',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});};
render(false);
